class LongestAlternatingSequence {
  public int solve(int[] sales) {
    int l = 0, r = 0;
    int curMax = 0;
    while (r < sales.length) {
      boolean canGrow = l == r || (sales[r - 1] >= 10) != (sales[r] >= 10);
      if (canGrow) {
        r++;
        curMax = Math.max(curMax, r - l);
      } else {
        l = r;
        r++;
      }
    }
    return curMax;
  }
}

